import{_ as l,C as r,o as n,c as s,j as t,a as e,E as o,a5 as c}from"./chunks/framework.CyyS6Zdm.js";const f=JSON.parse('{"title":"签名板","description":"","frontmatter":{},"headers":[],"relativePath":"components/signature-pad.md","filePath":"components/signature-pad.md","lastUpdated":1787185306000}'),h={name:"components/signature-pad.md"},u={id:"签名板",tabindex:"-1"};function g(p,d,b,m,x,P){const i=r("Badge"),a=r("XhDemo");return n(),s("div",null,[t("h1",u,[d[0]||(d[0]=e("签名板 ",-1)),o(i,{type:"info",text:"signature-pad"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#签名板","aria-label":'Permalink to "签名板 <Badge type="info" text="signature-pad" />"'},"​",-1))]),d[3]||(d[3]=c('<p>一块用指针写字的画布：按下落笔、移动成迹、抬笔收一笔，画出来的是可缩放、可直接提交的 SVG。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>承诺书、回执、验收单上要留一笔手写签名。</li><li>交付确认、上门服务签收这类要留下&quot;人到过、看过&quot;的痕迹的场景。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>要的是一份已有的签名图片：那是上传，用<a href="./file-upload">文件上传</a>。</li><li>要的是打字签名或姓名核对：那是一行文本，用<a href="./text-field">文本输入</a>。</li><li>要的是在图片上圈画批注：本组件只画自己那块画布，不承载底图。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>笔迹是 SVG 填充路径，放大不糊；每一笔是同一条路径上的一条子路径。</li><li>第一笔落下时量一次画布并把这套坐标钉住，画布的 <code>viewBox</code> 与导出的 SVG 都写它：容器变宽变窄时，已有笔迹跟着缩放而不是留在原像素上错位。清空后重新量。</li><li><code>drawing</code> 一组选项调笔画外形：<code>size</code> 定粗细，<code>thinning</code> 让粗细随压感变，<code>simulatePressure</code> 决定压感是取设备值还是按落笔速度算。</li><li>带 <code>name</code> 即参与表单提交，提交的是一份独立的 SVG 文档；表单重置会把画布清回空。</li><li>笔迹变了就发 <code>draw</code>，签名定稿就发 <code>draw-end</code>——抬笔、点清空、表单重置这三条路径都发。照 <code>draw-end</code> 缓存待提交的 SVG 不会拿到过期的那一版。</li><li>手划出画布甚至划出窗口都跟手，抬手即收笔；落笔那根指针被捕获，手掌与第二根手指的移动不会被续进这一笔。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一块画布加一条笔迹路径就够了：按下落笔、移动成迹、抬笔收一笔</p>',10)),o(a,{src:"signature-pad/01-basic"}),d[4]||(d[4]=t("h3",{id:"标题、基准线与清空",tabindex:"-1"},[e("标题、基准线与清空 "),t("a",{class:"header-anchor",href:"#标题、基准线与清空","aria-label":'Permalink to "标题、基准线与清空"'},"​")],-1)),d[5]||(d[5]=t("p",null,"基准线是纯画面（带 aria-hidden），清空按钮是原生 button，读屏念的是 translations 里那句",-1)),o(a,{src:"signature-pad/02-guide"}),d[6]||(d[6]=t("h3",{id:"参与表单",tabindex:"-1"},[e("参与表单 "),t("a",{class:"header-anchor",href:"#参与表单","aria-label":'Permalink to "参与表单"'},"​")],-1)),d[7]||(d[7]=t("p",null,"给了 name 就带上表单影子，提交的是一份独立 SVG；表单重置会把画布清回空",-1)),o(a,{src:"signature-pad/03-form"}),d[8]||(d[8]=t("h3",{id:"笔迹外形",tabindex:"-1"},[e("笔迹外形 "),t("a",{class:"header-anchor",href:"#笔迹外形","aria-label":'Permalink to "笔迹外形"'},"​")],-1)),d[9]||(d[9]=t("p",null,"drawing 调笔宽与压感：thinning 越大，划得越快笔画越细，simulatePressure 决定压感取设备值还是按速度算",-1)),o(a,{src:"signature-pad/04-pen"}),d[10]||(d[10]=t("h3",{id:"只读与禁用",tabindex:"-1"},[e("只读与禁用 "),t("a",{class:"header-anchor",href:"#只读与禁用","aria-label":'Permalink to "只读与禁用"'},"​")],-1)),d[11]||(d[11]=t("p",null,"只读画好的还看得见但改不动，禁用连清空按钮都按不动；两者都走原生 disabled，不是灰一层了事",-1)),o(a,{src:"signature-pad/05-readonly-disabled"}),d[12]||(d[12]=t("h3",{id:"取出签名",tabindex:"-1"},[e("取出签名 "),t("a",{class:"header-anchor",href:"#取出签名","aria-label":'Permalink to "取出签名"'},"​")],-1)),d[13]||(d[13]=t("p",null,"签名定稿时 draw-end 带上一份可直接落库的 SVG；提交前用 empty 拦一道，空签名不该走出客户端",-1)),o(a,{src:"signature-pad/06-export"}),d[14]||(d[14]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-signature-pad&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhSignaturePadClearTrigger</code> <code>XhSignaturePadControl</code> <code>XhSignaturePadGuide</code> <code>XhSignaturePadHiddenInput</code> <code>XhSignaturePadLabel</code> <code>XhSignaturePadRoot</code> <code>XhSignaturePadSegment</code> <code>XhSignaturePadStatus</code></td></tr><tr><td>组合式函数</td><td><code>useSignaturePad</code></td></tr><tr><td>状态机</td><td><code>signaturePadMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/signature-pad.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;signature-pad&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <strong><code>control</code></strong> · <code>guide</code> · <strong><code>segment</code></strong> · <code>clear-trigger</code> · <code>status</code> · <code>hidden-input</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整块不可交互：落笔不认，清空按钮也按不动。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：画好的签名照常显示，但改不动。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验未通过的标记，只改外观与表单影子上的 aria-invalid。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了表单影子才带 name 并参与提交。</td></tr><tr><td><code>drawing</code></td><td><code>SignaturePadDrawingOptions</code></td><td></td><td>笔迹外形。缺省即 4px 恒定粗细。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;SignaturePadTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onDraw</code></td><td><code>(details: SignaturePadDrawDetails) =&gt; void</code></td><td></td><td>每收进一个点通知一次，清空与表单重置时也通知一次（路径为空）。</td></tr><tr><td><code>onDrawEnd</code></td><td><code>(details: SignaturePadDrawEndDetails) =&gt; void</code></td><td></td><td>签名定稿时通知一次并带上可直接提交的 SVG：抬笔、清空、表单重置这三条路径都发。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>draw</code></td><td><code>SignaturePadDrawDetails</code></td><td>笔迹变了就通知一次（含清空与表单重置）；detail 为 <code>{ paths: string[], path: string }</code></td></tr><tr><td><code>draw-end</code></td><td><code>SignaturePadDrawEndDetails</code></td><td>签名定稿时通知一次（抬笔、清空、表单重置）；detail 为 <code>{ paths: string[], svg: string }</code>，svg 可直接落库</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhSignaturePadRoot</code></td><td><code>default</code></td><td><code>SignaturePadRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>status</code></td><td>&#39;empty&#39; | &#39;signed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>drawing</code> · <code>idle</code></p><p><strong>事件</strong>：<code>DRAW.START</code> · <code>DRAW.MOVE</code> · <code>DRAW.END</code> · <code>STROKES.CLEAR</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>canDraw</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useSignaturePad</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>paths</code></td><td><code>readonly string[]</code></td><td>逐笔的填充轮廓 d 串，按落笔先后排列。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>一笔都没画。</td></tr><tr><td><code>drawing</code></td><td><code>boolean</code></td><td>笔正落在画布上。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>statusText</code></td><td><code>string</code></td><td>签没签的那句话，写进 status 部件；适配器在作者没自己写文字时把它填进节点。</td></tr><tr><td><code>toSvg</code></td><td><code>() =&gt; string</code></td><td>当前签名的独立 SVG 文档，与表单影子提交的是同一份；空签名为空串。</td></tr><tr><td><code>clear</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGuideProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSegmentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getClearTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getStatusProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>状态出口：一块 role=status 的活区域，签上与清空都会播报一次。</td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单出口：一份视觉隐藏的原生输入，随表单提交当前签名。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on clear-trigger, 未禁用且非只读</td><td>清空整块画布；按钮是原生 button，这两个键由平台翻成 click</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>control</code></td><td><code>aria-label</code></td><td>translations?.label</td></tr><tr><td><code>control</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>control</code></td><td><code>role</code></td><td>&#39;img&#39;</td></tr><tr><td><code>guide</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>clear-trigger</code></td><td><code>aria-label</code></td><td>translations?.clearTrigger</td></tr><tr><td><code>status</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>status</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>status</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr></tbody></table><ul><li><strong>签名天然依赖指针，用键盘和读屏做不出来。凡是要求签名的流程，必须同时提供一条不依赖指针的替代路径</strong>——打字签名、上传签名图、或线下核验。只放一块画布就等于把这些用户挡在流程之外。</li><li>画布报的是 <code>role=&quot;img&quot;</code>，不是控件：它不接键盘、不进 Tab 序列，把它伪装成控件只会让读屏用户走进一个走不通的地方。</li><li>画布的名字来自 <code>label</code> 部件；没渲染标题时退回 <code>translations.label</code>。</li><li><strong>签没签靠 <code>status</code> 部件播报</strong>。画布是 <code>role=&quot;img&quot;</code>，名字恒定，签上、清空、表单重置之后读屏念出来都是同一句话，用户无从确认自己那一笔留住了没有。<code>status</code> 是一块 <code>role=&quot;status&quot;</code> 的活区域，值变一次播报一次，文案走 <code>translations.statusEmpty</code> / <code>translations.statusSigned</code>。要求签名的表单请把它渲染出来。</li><li>基准线是纯画面，带 <code>aria-hidden</code>，读屏不会念它。没有 <code>translations.guide</code> 这条文案：给一条装饰线起名字只会让读屏多念一句没有信息量的话。</li><li>清空按钮是原生 <code>&lt;button&gt;</code>，Enter / Space 由平台激活；按钮里只放图标时读屏念的是 <code>translations.clearTrigger</code>。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/signature-pad.css</code> 按部件选择：<code>[data-scope=&quot;signature-pad&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-drawing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-drawing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>guide</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>segment</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>clear-trigger</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>status</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>status</code></td><td><code>data-state</code></td><td>&#39;empty&#39; | &#39;signed&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-signature-pad-aspect-ratio</code> · <code>--xh-signature-pad-bg</code> · <code>--xh-signature-pad-bg-disabled</code> · <code>--xh-signature-pad-border</code> · <code>--xh-signature-pad-border-drawing</code> · <code>--xh-signature-pad-clear-bg</code> · <code>--xh-signature-pad-clear-bg-disabled</code> · <code>--xh-signature-pad-clear-bg-hover</code> · <code>--xh-signature-pad-clear-border</code> · <code>--xh-signature-pad-clear-fg</code> · <code>--xh-signature-pad-clear-gap</code> · <code>--xh-signature-pad-clear-h</code> · <code>--xh-signature-pad-clear-px</code> · <code>--xh-signature-pad-clear-radius</code> · <code>--xh-signature-pad-gap</code> · <code>--xh-signature-pad-guide-stroke</code> · <code>--xh-signature-pad-ink</code> · <code>--xh-signature-pad-label-fg</code> · <code>--xh-signature-pad-label-font-size</code> · <code>--xh-signature-pad-label-font-weight</code> · <code>--xh-signature-pad-radius</code> · <code>--xh-signature-pad-status-fg</code> · <code>--xh-signature-pad-status-font-size</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><ul><li>画布宽度铺满外层容器，高度由宽高比（<code>--xh-signature-pad-aspect-ratio</code>，默认 5 / 2）决定，窄屏上自动变矮。</li><li>签到一半转屏、拖动面板改宽度，已有笔迹按 <code>viewBox</code> 整体缩放，接着写下去的新笔与它落在同一套坐标里。</li><li>触摸设备上画布关掉了浏览器的滚动与缩放手势，否则手指一划页面就滚走了。</li></ul><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>画布与基准线不分左右：笔迹按落笔坐标记录，方向由写的人决定。</li><li>标题与清空按钮的排布跟着文档方向走，皮肤全用逻辑属性。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./field">字段</a>搭配：标题、说明与错误提示交给字段，签名板只管画布。</li><li>放进<a href="./form">表单</a>里，<code>name</code> 一给就跟着提交与重置走。</li><li>与<a href="./dialog">对话框</a>搭配做&quot;签名确认&quot;：确认按钮的可用状态读 <code>empty</code>。</li></ul><h3 id="节点形状是硬约束" tabindex="-1">节点形状是硬约束 <a class="header-anchor" href="#节点形状是硬约束" aria-label="Permalink to &quot;节点形状是硬约束&quot;">​</a></h3><p>画布这一族部件必须落在特定标签上，写错了不会报错，只是一笔都画不出来：</p><ul><li><code>control</code> 必须是 <code>&lt;svg&gt;</code>；</li><li><code>guide</code> 必须是 <code>control</code> 里面的 <code>&lt;line&gt;</code>；</li><li><code>segment</code> 必须是 <code>control</code> 里面的 <code>&lt;path&gt;</code>；</li><li><code>clear-trigger</code> 必须是原生 <code>&lt;button&gt;</code>，<code>hidden-input</code> 必须是原生 <code>&lt;input&gt;</code>。</li></ul><p><code>viewBox</code> 由组件自己写，作者不要在 <code>control</code> 上再写一个。</p><h3 id="两个适配器的分工" tabindex="-1">两个适配器的分工 <a class="header-anchor" href="#两个适配器的分工" aria-label="Permalink to &quot;两个适配器的分工&quot;">​</a></h3><ul><li><strong>Vue</strong>：<code>XhSignaturePadRoot</code> 的默认插槽给出 <code>empty</code> / <code>paths</code> / <code>drawing</code> / <code>statusText</code> 与 <code>toSvg()</code> / <code>clear()</code>；也可以用 <code>useSignaturePad()</code> 自己拿。<code>XhSignaturePadGuide</code> 与 <code>XhSignaturePadSegment</code> 必须写在 <code>XhSignaturePadControl</code> 里面——SVG 命名空间由那棵子树带下去，挪出去就成了 HTML 元素，画不出东西。</li><li><strong>Web Components</strong>：结构由作者自己写（Light DOM，不投影插槽）。<code>&lt;xh-signature-pad&gt;</code> 上有 <code>clear()</code>、<code>toSvg()</code> 与只读的 <code>empty</code>；提交前取签名用 <code>toSvg()</code>，不必去缓存上一次 <code>draw-end</code>。</li><li>两边的 <code>status</code> 部件里都不必自己写字：节点为空时由适配器填内建文案；写了字就以作者写的为准。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>给清空按钮留一句可见文字或稳定的图标语义，别只靠一个叉。</li><li><strong>清空之后要把焦点安顿好</strong>：按钮被禁用或被收起时焦点会掉回 <code>&lt;body&gt;</code>，键盘用户每清一次就丢一次位置。要么让按钮始终可按（本组件的默认做法），要么清空后显式把焦点交给下一个落点。</li><li>提交前用 <code>empty</code> 拦一道：空签名与&quot;签了但很潦草&quot;是两回事，前者应该在客户端就挡住。</li><li>要缓存待提交的 SVG 就照 <code>draw-end</code> 缓存：清空与表单重置同样会发它，缓存不会停在旧的那一版。不要去嗅探清空按钮的点击。</li><li>存的是 SVG 文本，不是位图。要生成位图请在服务端渲染，别在前端截屏。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把画布做成小小一条：手写需要面积，太窄的画布只会逼人写出自己都认不出的字。</li><li>让签名成为唯一的确认方式，却不给替代路径——这是可达性问题，不是体验问题。</li><li>拿签名图当身份凭证。它证明的是&quot;有人在这块画布上划过&quot;，不是&quot;谁划的&quot;。</li></ul>',58))])}const S=l(h,[["render",g]]);export{f as __pageData,S as default};
